  .attr("x", margin.left + x(30.5)) // Aligned with Fox News Independent midpoint (25-36)
  .attr("y", labelY)
  .attr("text-anchor", "middle")
  .attr("dominant-baseline", "alphabetic")
  .style("font-family", "sans-serif")
  .style("font-size", "26px")
  .style("font-weight", "700")
  .style("fill", "#7A7A7A")
  .text("Independent");

labelLayer
  .append("text")
  .attr("x", margin.left + x(68)) // Aligned with Fox News Republican midpoint (36-100)
  .attr("y", labelY)
  .attr("text-anchor", "middle") // Centered over the segment group
  .attr("dominant-baseline", "alphabetic")
  .style("font-family", "sans-serif")
  .style("font-size", "26px")
  .style("font-weight", "700")
  .style("fill", "#E10F0F")
  .text("Republican");

// --- Segment labels inside Fox News and MSNBC only ---
// This section already implements tasks (2) and (3)
function segmentLabel(d) {
  if (d.outlet === "Fox News") {
    if (d.category === "Lean Republican") return "Lean";
    if (d.category === "Weak Republican") return "Weak";
    if (d.category === "Strong Republican") return "Strong";
  }
  if (d.outlet === "MSNBC") {
    if (d.category === "Strong Democrat") return "Strong";
    if (d.category === "Weak Democrat") return "Weak";
    if (d.category === "Lean Democrat") return "Lean";
  }
  return "";
}

const labeled = stacked
  .map(d => ({ ...d, segLabel: segmentLabel(d) }))
  .filter(d => d.segLabel !== "");

g.append("g")
  .selectAll("text")
  .data(labeled)
  .join("text")
  .attr("x", d => x(d.mid))
  .attr("y", d => y(d.outlet) + y.bandwidth() / 2)
  .attr("text-anchor", "middle")
  .attr("dominant-baseline", "middle")
  .style("font-family", "sans-serif")
  .style("font-size", "26px")
  .style("font-weight", "700")
  .style("fill", "#fff")
  .text(d => d.segLabel);

// --- Utility function for text wrapping ---
function wrapText(text, width) {
  text.each(function() {
    let text = d3.select(this),
      words = text.text().split(/\s+/).reverse(),
      word,
      line = [],
      lineNumber = 0,
      lineHeight = 1.2, // ems
      y = text.attr("y"),
      x = text.attr("x"),
      dy = parseFloat(text.attr("dy") || 0),
      tspan = text.text(null).append("tspan").attr("x", x).attr("y", y).attr("dy", dy + "em");

    while ((word = words.pop())) {
      line.push(word);
      tspan.text(line.join(" "));
      if (tspan.node().getComputedTextLength() > width) {
        line.pop();
        tspan.text(line.join(" "));
        line = [word];
        tspan = text.append("tspan").attr("x", x).attr("y", y).attr("dy", ++lineNumber * lineHeight + dy + "em").text(word);
      }
    }
  });
}

// --- Callout box for Fox News (Task 4) ---
const calloutText = "Fox viewers skew to the right—but most are not committed Republicans";

// Target point on the Fox News bar (e.g., in the Lean Republican segment)
const targetX = margin.left + x(50); // 50% mark on the x-axis
const targetY = margin.top + y("Fox News") + y.bandwidth() / 2; // Vertical center of Fox News bar

// Callout group
const calloutGroup = svg.append("g");

// Add text first to get its bounding box
const textElement = calloutGroup
  .append("text")
  .attr("x", 0) // Temporary x, will be adjusted after box calculation
  .attr("y", 0) // Temporary y, will be adjusted after box calculation
  .attr("text-anchor", "start")
  .attr("dominant-baseline", "hanging") // y is the top of the text
  .style("font-family", "sans-serif")
  .style("font-size", "20px")
  .style("font-weight", "400")
  .style("fill", "#333")
  .text(calloutText)
  .call(wrapText, 200); // Wrap text within 200px width

// Get bounding box of the wrapped text
const textBBox = textElement.node().getBBox();
const textPadding = 10;

// Calculate box dimensions and position
const boxWidth = textBBox.width + 2 * textPadding;
const boxHeight = textBBox.height + 2 * textPadding;

// Position the box to the right of the chart, vertically centered with targetY
const calloutBoxX = margin.left + innerW + 50; // 50px to the right of the chart area
const calloutBoxY = targetY - boxHeight / 2; // Center vertically with targetY

// Add rectangle for the callout box
calloutGroup
  .insert("rect", "text") // Insert before the text element
  .attr("x", calloutBoxX)
  .attr("y", calloutBoxY)
  .attr("width", boxWidth)
  .attr("height", boxHeight)
  .attr("fill", "#f0fef0") // Light green background for callout
  .attr("stroke", "#66bb6a") // Green border
  .attr("stroke-width", 1.5)
  .attr("rx", 5) // Rounded corners
  .attr("ry", 5);

// Reposition the text inside the box
textElement
  .attr("x", calloutBoxX + textPadding)
  .attr("y", calloutBoxY + textPadding);

// Add a line connecting the callout box to the target point
calloutGroup
  .append("line")
  .attr("x1", calloutBoxX) // Left edge of the box
  .attr("y1", calloutBoxY + boxHeight / 2) // Middle of the box vertically
  .attr("x2", targetX)
  .attr("y2", targetY)
  .attr("stroke", "#66bb6a") // Green line
  .attr("stroke-width", 2)
  .attr("marker-end", "url(#arrowhead)"); // Add an arrowhead

// Define arrowhead marker
svg
  .append("defs")
  .append("marker")
  .attr("id", "arrowhead")
  .attr("viewBox", "0 -5 10 10")
  .attr("refX", 5) // Point of the arrow
  .attr("refY", 0)
  .attr("markerWidth", 6)
  .attr("markerHeight", 6)
  .attr("orient", "auto") // Orient arrow along the path, pointing to x2,y2
  .append("path")
  .attr("d", "M0,-5L10,0L0,5")
  .attr("fill", "#66bb6a"); // Green arrowhead
