  { year: 2001, cat: "Other", value: 18 },
  { year: 2002, cat: "Other", value: 20 },
  { year: 2003, cat: "Other", value: 32 },
  { year: 2004, cat: "Other", value: 75 },

  { year: 2005, cat: "Hurricane Katrina", value: 161 },
  { year: 2005, cat: "Other", value: 55 },

  { year: 2006, cat: "Other", value: 20 },
  { year: 2007, cat: "Other", value: 14 },
  { year: 2008, cat: "Other", value: 72 },
  { year: 2009, cat: "Other", value: 18 },
  { year: 2010, cat: "Other", value: 16 },
  { year: 2011, cat: "Other", value: 58 },
  { year: 2012, cat: "Other", value: 78 },
  { year: 2013, cat: "Other", value: 125 },
  { year: 2014, cat: "Other", value: 32 },
  { year: 2015, cat: "Other", value: 24 },
  { year: 2016, cat: "Other", value: 28 },

  { year: 2017, cat: "Hurricane Harvey", value: 125 },
  { year: 2017, cat: "Hurricane Maria", value: 90 },
  { year: 2017, cat: "Hurricane Irma", value: 50 },
  { year: 2017, cat: "California wildfires", value: 18 },
  { year: 2017, cat: "Other", value: 22 }
];

// --- Layout ---
const innerWidth = 820;
const innerHeight = 420;
const margin = { top: 40, right: 70, bottom: 55, left: 240 };
const width = innerWidth + margin.left + margin.right;
const height = innerHeight + margin.top + margin.bottom;

// --- Colors (match look: pale pink vs deep red) ---
const color = (cat) => (cat === "Other" ? "#f6bfb9" : "#cc0000");

// --- Prepare stacked segments per year (sorted by cat ascending) ---
const years = Array.from(new Set(data.map(d => d.year))).sort((a, b) => a - b);

const byYear = d3.group(data, d => d.year);
const segments = [];
for (const y of years) {
  const arr = (byYear.get(y) || []).slice().sort((a, b) => d3.ascending(a.cat, b.cat));
  let y0 = 0;
  for (const d of arr) {
    const y1 = y0 + d.value;
    segments.push({ year: y, cat: d.cat, value: d.value, y0, y1 });
    y0 = y1;
  }
}

// --- Scales ---
const x = d3.scaleBand()
  .domain(years)
  .range([0, innerWidth])
  .paddingInner(0.45)
  .paddingOuter(0.18);

const y = d3.scaleLinear()
  .domain([0, 310])
  .range([innerHeight, 0]);

// --- SVG ---
const svg = d3.select("body")
  .append("svg")
  .attr("width", width)
  .attr("height", height)
  .style("background", "white");

// Title
svg.append("text")
  .attr("x", width / 2)
  .attr("y", 24)
  .attr("text-anchor", "middle")
  .attr("font-family", "Arial")
  .attr("font-size", 13)
  .attr("font-weight", "bold")
  .attr("fill", "#222")
  .text("GRAPH B");

// Left-side description text (in left padding area)
svg.append("text")
  .attr("x", 30)
  .attr("y", margin.top + 95)
  .attr("text-anchor", "start")
  .attr("font-family", "Arial")
  .attr("font-size", 13)
  .attr("font-weight", "bold")
  .attr("fill", "#222")
  .attr("dominant-baseline", "hanging")
  .selectAll("tspan")
  .data(["Total cost of major", "natural disasters"])
  .enter()
  .append("tspan")
  .attr("x", 30)
  .attr("dy", (d, i) => (i === 0 ? 0 : 16))
  .text(d => d);

svg.append("text")
  .attr("x", 30)
  .attr("y", margin.top + 140)
  .attr("text-anchor", "start")
  .attr("font-family", "Arial")
  .attr("font-size", 11)
  .attr("fill", "#666")
  .attr("dominant-baseline", "hanging")
  .selectAll("tspan")
  .data(["For disasters causing more", "than $1 billion in losses."])
  .enter()
  .append("tspan")
  .attr("x", 30)
  .attr("dy", (d, i) => (i === 0 ? 0 : 15))
  .text(d => d);

// Plot group
const g = svg.append("g")
  .attr("transform", `translate(${margin.left},${margin.top})`);

// Horizontal gridlines at specific ticks (dashed)
const gridVals = [50, 100, 150, 200, 250, 300];
g.append("g")
  .selectAll("line")
  .data(gridVals)
  .enter()
  .append("line")
  .attr("x1", 0)
  .attr("x2", innerWidth)
  .attr("y1", d => y(d))
  .attr("y2", d => y(d))
  .attr("stroke", "#d6d6d6")
  .attr("stroke-width", 1)
  .attr("stroke-dasharray", "2,2");

// Bars (stacked)
g.append("g")
  .selectAll("rect")
  .data(segments)
  .enter()
  .append("rect")
  .attr("x", d => x(d.year))
  .attr("width", x.bandwidth())
  .attr("y", d => y(d.y1))
  .attr("height", d => Math.max(0, y(d.y0) - y(d.y1)))
  .attr("fill", d => color(d.cat));

// Y axis (left): labels only, no domain/ticks; custom labels with $300 billion
const yAxis = d3.axisLeft(y)
  .tickValues(gridVals)
  .tickSize(0)
  .tickFormat(d => (d === 300 ? "$300 billion" : d));

g.append("g")
  .call(yAxis)
  .call(sel => sel.select(".domain").remove())
  .call(sel => sel.selectAll("text")
    .attr("font-family", "Arial")
    .attr("font-size", 11)
    .attr("fill", "#666")
    .attr("dx", "-0.2em")
  );

// X axis (bottom): label only every 5 years; no ticks/domain
const xAxis = d3.axisBottom(x)
  .tickSize(0)
  .tickFormat(d => (d % 5 === 0 ? d : ""));

g.append("g")
  .attr("transform", `translate(0,${innerHeight})`)
  .call(xAxis)
  .call(sel => sel.select(".domain").remove())
  .call(sel => sel.selectAll("text")
    .attr("font-family", "Arial")
    .attr("font-size", 11)
    .attr("fill", "#666")
    .attr("dy", "1.0em")
  );

// ------------------------------
// Asked changes: labels + 2017 $300B reference
// ------------------------------

// Helper: find a specific segment
function findSegment(year, cat) {
  return segments.find(s => s.year === year && s.cat === cat);
}

// Labels to add (costliest disasters)
const labelSpecs = [
  { year: 2005, cat: "Hurricane Katrina", text: "Hurricane Katrina\n$161 billion" },
  { year: 2017, cat: "California wildfires", text: "California wildfires\n$18 billion" },
  { year: 2017, cat: "Hurricane Irma", text: "Hurricane Irma\n$50 billion" },
  { year: 2017, cat: "Hurricane Maria", text: "Hurricane Maria\n$90 billion" },
  { year: 2017, cat: "Hurricane Harvey", text: "Hurricane Harvey\n$125 billion" }
].map(d => {
  const seg = findSegment(d.year, d.cat);
  return seg ? { ...d, seg } : null;
}).filter(Boolean);

// Label group
const labelsG = g.append("g").attr("class", "disaster-labels");

// Positioning tweaks to reduce overlap (especially for 2017 stack)
const labelOffset = (d) => {
  // default: to the right of the bar, centered on the segment
  let dx = 10;
  let dy = 0;

  if (d.year === 2017) {
    // Stagger labels vertically a bit to avoid collisions
    if (d.cat === "Hurricane Harvey") dy = -10;
    if (d.cat === "Hurricane Maria") dy = 0;
    if (d.cat === "Hurricane Irma") dy = 10;
    if (d.cat === "California wildfires") dy = 18;
  }

  if (d.year === 2005 && d.cat === "Hurricane Katrina") {
    dy = -6;
  }

  return { dx, dy };
};

// Add multi-line text labels
const label = labelsG.selectAll("text")
  .data(labelSpecs)
  .enter()
  .append("text")
  .attr("x", d => x(d.year) + x.bandwidth() + labelOffset(d).dx)
  .attr("y", d => {
    const mid = (d.seg.y0 + d.seg.y1) / 2;
    return y(mid) + labelOffset(d).dy;
  })
  .attr("text-anchor", "start")
  .attr("dominant-baseline", "middle")
  .attr("font-family", "Arial")
  .attr("font-size", 11)
  .attr("fill", "#222");

label.selectAll("tspan")
  .data(d => d.text.split("\n").map((line, i) => ({ line, i })))
  .enter()
  .append("tspan")
  .attr("x", function(_, i) {
    // keep same x for each line
    return d3.select(this.parentNode).attr("x");
  })
