    .each(function (d) {
      const t = d3.select(this);
      const m = monthFmt(d);
      const isAug = m === "Aug.";
      const isFeb = m === "Feb.";

      t.append("tspan").attr("x", 0).text(m);

      if (isAug || isFeb) {
        t.append("tspan").attr("x", 0).attr("dy", "1.15em").text(yearFmt(d));
      }
    });

  // Line generator
  const line = d3
    .line()
    .x(d => x(d.date))
    .y(d => y(d.value))
    .curve(d3.curveLinear);

  const series = d3.group(data, d => d.series);

  // Draw lines
  g.append("g")
    .selectAll("path.series-line")
    .data(Array.from(series, ([key, values]) => ({ key, values: values.slice().sort((a, b) => a.date - b.date) })))
    .join("path")
    .attr("class", "series-line")
    .attr("fill", "none")
    .attr("stroke", d => colors.get(d.key))
    .attr("stroke-width", 2.8)
    .attr("stroke-linecap", "round")
    .attr("stroke-linejoin", "round")
    .attr("d", d => line(d.values));

  // Last points + end labels
  const lastPoints = Array.from(series, ([key, values]) => {
    const v = values.slice().sort((a, b) => a.date - b.date);
    const last = v[v.length - 1];
    // Store the label information (name and explanation)
    const labelInfo = labelParts.get(key);
    return { key, ...last, labelInfo };
  });

  // End dots
  g.append("g")
    .selectAll("circle.end-dot")
    .data(lastPoints)
    .join("circle")
    .attr("class", "end-dot")
    .attr("cx", d => x(d.date))
    .attr("cy", d => y(d.value))
    .attr("r", 6) // size ~ 85 in Vega; this is visually close
    .attr("fill", d => colors.get(d.key))
    .attr("stroke", "none");

  // End labels (modified to include series name + explanation, multi-line)
  g.append("g")
    .selectAll("text.end-label")
    .data(lastPoints)
    .join("text")
    .attr("class", "end-label")
    .attr("x", d => x(d.date) + 25) // Increased offset for longer text
    .attr("y", d => y(d.value))
    .attr("text-anchor", "start")
    // Removed dominant-baseline to allow tspan dy to control vertical alignment
    .style("font-size", "12px")
    .attr("fill", d => colors.get(d.key))
    .each(function(d) {
      const textElement = d3.select(this);
      // Series name (bold)
      textElement.append("tspan")
        .attr("x", x(d.date) + 25) // Ensure x is set for each tspan for multi-line
        .attr("dy", "-0.6em") // Adjust vertical position for first line (moves it up relative to the dot's y)
        .style("font-weight", "700")
        .text(d.labelInfo.name);

      // Explanation (normal weight)
      textElement.append("tspan")
        .attr("x", x(d.date) + 25) // Ensure x is set for each tspan for multi-line
        .attr("dy", "1.2em") // Line height for second line (relative to previous tspan)
        .style("font-weight", "400")
        .text(d.labelInfo.explanation);
    });
})();
