{
  "$schema": "https://vega.github.io/schema/vega/v6.json",
  "description": "A scatter plot with trend line calculated via user-configurable regression methods, highlighting the group of data points that deviate most from their respective regression trend.",
  "padding": 5,
  "width": 500,
  "height": 500,
  "autosize": "pad",

  "signals": [
    {
      "name": "method", "value": "linear",
      "bind": {"input": "select", "options": [
        "linear", "log", "exp", "pow", "quad", "poly"
      ]}
    },
    {
      "name": "polyOrder", "value": 3,
      "bind": {"input": "range", "min": 1, "max": 10, "step": 1}
    },
    {
      "name": "groupby", "value": "none",
      "bind": {"input": "select", "options": ["none", "genre"]}
    },
    {
      "name": "groupbyField",
      "update": "groupby === 'genre' ? 'Major Genre' : 'dummy_group'"
    },
    {
      "name": "highlightGroupValue",
      "update": "data('max_deviation_group')[0] ? data('max_deviation_group')[0][groupbyField] : null"
    }
  ],

  "data": [
    {
      "name": "movies",
      "url": "data/movies.json",
      "transform": [
        {
          "type": "filter",
          "expr": "datum['Rotten Tomatoes Rating'] != null && datum['IMDB Rating'] != null"
        },
        {
          "type": "formula",
          "as": "dummy_group",
          "expr": "'all_movies'"
        }
      ]
    },
    {
      "name": "trend_lines",
      "source": "movies",
      "transform": [
        {
          "type": "regression",
          "groupby": [{"signal": "groupbyField"}],
          "method": {"signal": "method"},
          "order": {"signal": "polyOrder"},
          "extent": {"signal": "domain('x')"},
          "x": "Rotten Tomatoes Rating",
          "y": "IMDB Rating",
          "as": ["u", "v"]
        }
      ]
    },
    {
      "name": "trend_models",
      "source": "movies",
      "transform": [
        {
          "type": "regression",
          "groupby": [{"signal": "groupbyField"}],
          "method": {"signal": "method"},
          "order": {"signal": "polyOrder"},
          "x": "Rotten Tomatoes Rating",
          "y": "IMDB Rating",
          "output": {"model": "model_params"}
        }
      ]
    },
    {
      "name": "movies_with_predictions",
      "source": "movies",
      "transform": [
        {
          "type": "lookup",
          "from": "trend_models",
          "key": {"signal": "groupbyField"},
          "fields": [{"signal": "groupbyField"}],
          "as": ["trend_model_data"]
        },
        {
          "type": "formula",
          "as": "predicted_y",
          "expr": "var model = datum.trend_model_data.model_params; " +
                  "var x = datum['Rotten Tomatoes Rating']; " +
                  "var y_pred; " +
                  "if (model && model.length > 0) { " +
                    "if (method === 'linear' || method === 'quad' || method === 'poly') { " +
                      "y_pred = model[0]; " +
                      "for (var i = 1; i < model.length; ++i) { y_pred += model[i] * pow(x, i); } " +
                    "} " +
                    "else if (method === 'log') { y_pred = model[0] + model[1] * log(x); } " +
                    "else if (method === 'exp') { y_pred = exp(model[0]) * exp(model[1] * x); } " +
                    "else if (method === 'pow') { y_pred = exp(model[0]) * pow(x, model[1]); } " +
                    "else { y_pred = null; } " +
                  "} else { y_pred = null; } " +
                  "y_pred"
        },
        {
          "type": "formula",
          "as": "residual",
          "expr": "abs(datum['IMDB Rating'] - datum.predicted_y)"
        }
      ]
    },
    {
      "name": "group_deviations",
      "source": "movies_with_predictions",
      "transform": [
        {
          "type": "aggregate",
          "groupby": [{"signal": "groupbyField"}],
          "fields": ["residual"],
          "ops": ["mean"],
          "as": ["mean_abs_residual"]
        }
      ]
    },
    {
      "name": "max_deviation_group",
      "source": "group_deviations",
      "transform": [
        {
          "type": "window",
          "ops": ["rank"],
          "as": ["rank_deviation"],
          "sort": {"field": "mean_abs_residual", "order": "descending"}
        },
        {
          "type": "filter",
          "expr": "datum.rank_deviation === 1"
        }
      ]
    }
  ],

  "scales": [
    {
      "name": "x",
      "type": "linear",
      "domain": {"data": "movies", "field": "Rotten Tomatoes Rating"},
      "range": "width"
    },
    {
      "name": "y",
      "type": "linear",
      "domain": {"data": "movies", "field": "IMDB Rating"},
      "range": "height"
    },
    {
      "name": "color",
      "type": "ordinal",
      "domain": {"signal": "groupby === 'genre' ? data('movies', 'Major Genre') : []"},
      "range": "category"
    }
  ],

  "marks": [
    {
      "type": "symbol",
      "from": {"data": "movies_with_predictions"},
      "encode": {
        "enter": {
          "x": {"scale": "x", "field": "Rotten Tomatoes Rating"},
          "y": {"scale": "y", "field": "IMDB Rating"},
          "fillOpacity": {"value": 0.5},
          "size": {"value": 16}
        },
        "update": {
          "fill": [
            {
              "test": "datum[groupbyField] === highlightGroupValue && groupby === 'genre'",
              "value": "orange"
            },
            {"value": "steelblue"}
          ],
          "stroke": [
            {
              "test": "datum[groupbyField] === highlightGroupValue && groupby === 'genre'",
              "value": "darkorange"
            },
            {"value": "transparent"}
          ],
          "strokeWidth": [
            {
              "test": "datum[groupbyField] === highlightGroupValue && groupby === 'genre'",
              "value": 2
            },
            {"value": 0}
          ]
        }
      }
    },
    {
      "type": "group",
      "from": {
        "facet": {
          "data": "trend_lines",
          "name": "curve",
          "groupby": {"signal": "groupbyField"}
        }
      },
      "marks": [
        {
          "type": "line",
          "from": {"data": "curve"},
          "encode": {
            "enter": {
              "x": {"scale": "x", "field": "u"},
              "y": {"scale": "y", "field": "v"},
              "strokeWidth": {"value": 2}
            },
            "update": {
              "stroke": [
                {
                  "test": "groupby === 'genre'",
                  "scale": "color", "field": "Major Genre"
                },
                {"value": "firebrick"}
              ],
              "strokeOpacity": [
                {
                  "test": "groupby === 'genre' && datum[groupbyField] !== highlightGroupValue",
