          "x": {
            "scale": "xscale",
            "signal": "modeBin ? (modeBin.bin0 + modeBin.bin1) / 2 : 0"
          },
          "y": {
            "scale": "yscale",
            "signal": "modeBin ? modeBin.count : 0",
            "offset": -5
          },
          "opacity": {"signal": "modeBin ? 1 : 0"}
        }
      }
    }
  ]
}
