    },
    {
      "name": "maxDepth",
      "update": "data('tree').length > 0 ? max(data('tree'), 'depth') : 0"
    },
    {
      "name": "deepestNode",
      "update": "data('tree').length > 0 ? data('tree').filter(d => d.depth === maxDepth)[0] : null"
    },
    {
      "name": "prominentPathIds",
      "update": "deepestNode ? (function(node, treeData) { var path = []; var current = node; while (current) { path.push(current.id); current = treeData.find(d => d.id === current.parent); } return path; })(deepestNode, data('tree')) : []"
    }
  ],

  "data": [
    {
      "name": "tree",
      "url": "data/flare.json",
      "transform": [
        {
          "type": "stratify",
          "key": "id",
          "parentKey": "parent"
        },
        {
          "type": "tree",
          "method": {"signal": "layout"},
          "size": [{"signal": "height"}, {"signal": "width - 100"}],
          "separation": {"signal": "separation"},
          "as": ["y", "x", "depth", "children"]
        }
      ]
    },
    {
      "name": "links",
      "source": "tree",
      "transform": [
        { "type": "treelinks" },
        {
          "type": "formula",
          "as": "isProminentLink",
          "expr": "prominentPathIds.includes(datum.source.id) && prominentPathIds.includes(datum.target.id)"
        },
        {
          "type": "linkpath",
          "orient": "horizontal",
          "shape": {"signal": "links"}
        }
      ]
    }
  ],

  "scales": [
    {
      "name": "color",
      "type": "linear",
      "range": {"scheme": "magma"},
      "domain": {"data": "tree", "field": "depth"},
      "zero": true
    }
  ],

  "marks": [
    {
      "type": "path",
      "from": {"data": "links"},
      "encode": {
        "update": {
          "path": {"field": "path"},
          "stroke": {"signal": "datum.isProminentLink ? 'darkred' : '#ccc'"},
          "strokeWidth": {"signal": "datum.isProminentLink ? 2 : 1"}
        }
      }
    },
    {
      "type": "symbol",
      "from": {"data": "tree"},
      "encode": {
        "enter": {
          "size": {"value": 100}
        },
        "update": {
          "x": {"field": "x"},
          "y": {"field": "y"},
          "fill": {"signal": "prominentPathIds.includes(datum.id) ? 'red' : scale('color', datum.depth)"},
          "stroke": {"signal": "prominentPathIds.includes(datum.id) ? 'darkred' : '#fff'"},
          "strokeWidth": {"signal": "prominentPathIds.includes(datum.id) ? 2 : 1"}
        }
      }
    },
    {
      "type": "text",
      "from": {"data": "tree"},
      "encode": {
        "enter": {
