{
  "$schema": "https://vega.github.io/schema/vega/v6.json",
  "description": "An example of a radial layout for a node-link diagram of hierarchical data, with a highlighted 'animate' branch.",
  "width": 720,
  "height": 720,
  "padding": 5,
  "autosize": "none",

  "signals": [
    {
      "name": "labels", "value": true,
      "bind": {"input": "checkbox"}
    },
    {
      "name": "radius", "value": 280,
      "bind": {"input": "range", "min": 20, "max": 600}
    },
    {
      "name": "extent", "value": 360,
      "bind": {"input": "range", "min": 0, "max": 360, "step": 1}
    },
    {
      "name": "rotate", "value": 0,
      "bind": {"input": "range", "min": 0, "max": 360, "step": 1}
    },
    {
      "name": "layout", "value": "tidy",
      "bind": {"input": "radio", "options": ["tidy", "cluster"]}
    },
    {
      "name": "links", "value": "line",
      "bind": {
        "input": "select",
        "options": ["line", "curve", "diagonal", "orthogonal"]
      }
    },
    { "name": "originX", "update": "width / 2" },
    { "name": "originY", "update": "height / 2" }
  ],

  "data": [
    {
      "name": "tree",
      "url": "data/flare.json",
      "transform": [
        {
          "type": "stratify",
          "key": "id",
          "parentKey": "parent"
        },
        {
          "type": "tree",
          "method": {"signal": "layout"},
          "size": [1, {"signal": "radius"}],
          "as": ["alpha", "radius", "depth", "children"]
        },
        {
          "type": "formula",
          "expr": "(rotate + extent * datum.alpha + 270) % 360",
          "as":   "angle"
        },
        {
          "type": "formula",
          "expr": "PI * datum.angle / 180",
          "as":   "radians"
        },
        {
          "type": "formula",
          "expr": "inrange(datum.angle, [90, 270])",
          "as":   "leftside"
        },
        {
          "type": "formula",
          "expr": "originX + datum.radius * cos(datum.radians)",
          "as":   "x"
        },
        {
          "type": "formula",
          "expr": "originY + datum.radius * sin(datum.radians)",
          "as":   "y"
        }
      ]
    },
    {
      "name": "links",
      "source": "tree",
      "transform": [
        { "type": "treelinks" },
        {
          "type": "linkpath",
          "shape": {"signal": "links"}, "orient": "radial",
          "sourceX": "source.radians", "sourceY": "source.radius",
          "targetX": "target.radians", "targetY": "target.radius"
        }
      ]
    },
    {
      "name": "animateBranch",
      "source": "tree",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.id === 'flare.animate' || startsWith(datum.id, 'flare.animate.')"
        },
        {
          "type": "aggregate",
          "fields": ["angle", "angle", "radius", "radius"],
          "ops": ["min", "max", "min", "max"],
          "as": ["minAngle", "maxAngle", "minRadius", "maxRadius"]
        },
        {
          "type": "formula",
          "expr": "(datum.minAngle + datum.maxAngle) / 2",
          "as": "midAngle"
        },
        {
          "type": "formula",
          "expr": "PI * datum.midAngle / 180",
          "as": "midRadians"
        },
        {
          "type": "formula",
          "expr": "inrange(datum.midAngle, [90, 270])",
          "as": "leftside"
        }
      ]
    }
  ],

  "scales": [
    {
      "name": "color",
      "type": "linear",
      "range": {"scheme": "magma"},
      "domain": {"data": "tree", "field": "depth"},
      "zero": true
    }
  ],

  "marks": [
    {
      "type": "path",
      "from": {"data": "links"},
      "encode": {
        "update": {
          "x": {"signal": "originX"},
          "y": {"signal": "originY"},
          "path": {"field": "path"},
          "stroke": {"value": "#ccc"}
        }
      }
    },
    {
      "type": "symbol",
      "from": {"data": "tree"},
      "encode": {
        "enter": {
          "size": {"value": 100},
          "stroke": {"value": "#fff"}
        },
        "update": {
          "x": {"field": "x"},
          "y": {"field": "y"},
          "fill": {"scale": "color", "field": "depth"}
        }
      }
    },
    {
      "type": "text",
      "from": {"data": "tree"},
      "encode": {
        "enter": {
          "text": {"field": "name"},
          "fontSize": {"value": 9},
          "baseline": {"value": "middle"}
        },
        "update": {
          "x": {"field": "x"},
          "y": {"field": "y"},
          "dx": {"signal": "(datum.leftside ? -1 : 1) * 6"},
          "angle": {"signal": "datum.leftside ? datum.angle - 180 : datum.angle"},
          "align": {"signal": "datum.leftside ? 'right' : 'left'"},
          "opacity": {"signal": "labels ? 1 : 0"}
        }
      }
    },
    {
      "type": "arc",
      "from": {"data": "animateBranch"},
      "encode": {
        "update": {
          "x": {"signal": "originX"},
          "y": {"signal": "originY"},
          "innerRadius": {"signal": "max(1, datum.minRadius - 5)"},
          "outerRadius": {"signal": "datum.maxRadius + 5"},
          "startAngle": {"signal": "datum.minAngle * PI / 180"},
          "endAngle": {"signal": "datum.maxAngle * PI / 180"},
          "stroke": {"value": "red"},
          "strokeWidth": {"value": 2},
          "fill": {"value": "red"},
          "fillOpacity": {"value": 0.05}
        }
      }
    },
    {
      "type": "text",
      "from": {"data": "animateBranch"},
      "encode": {
        "enter": {
          "text": {"value": "Animate Branch"},
          "fontSize": {"value": 12},
          "fontWeight": {"value": "bold"},
          "fill": {"value": "red"},
          "baseline": {"value": "middle"}
        },
        "update": {
          "x": {"signal": "originX + (datum.maxRadius + 20) * cos(datum.midRadians)"},
          "y": {"signal": "originY + (datum.maxRadius + 20) * sin(datum.midRadians)"},
          "angle": {"signal": "datum.leftside ? datum.midAngle - 180 : datum.midAngle"},
          "align": {"signal": "datum.leftside ? 'right' : 'left'"}
        }
      }
    }
  ]
}
