          "source": "values",
          "transform": [
            {"type": "aggregate", "ops": ["max"], "fields": ["date"]}
          ]
        },
        {
          "name": "weeks",
          "transform": [
            {"type": "sequence", "start": 0, "stop": 53, "as": "weeknum"},
            {"type": "formula", "expr": "datetime(parent.year, 0, 1 + datum.weeknum * 7)", "as": "date"},
            {"type": "timeunit", "units": ["year", "week"], "field": "date", "as": ["w0", "w1"]},
            {"type": "formula", "expr": "timeOffset('day', datum.w0)", "as": "w0"},
            {"type": "filter", "expr": "datum.date < data('max')[0].max_date"}
          ]
        }
      ],

      "scales": [
        {
          "name": "x",
          "type": "band",
          "domain": {"data": "weeks", "field": "w0", "sort": true},
          "range": {"step": {"signal": "step"}}
        }
      ],

      "axes": [
        {
          "orient": "left", "scale": "y",
          "ticks": false, "domain": false, "labelPadding": 8,
          "format": "%a", "formatType": "time",
          "title": {"signal": "parent.year"},
          "titleAngle": 0, "titleAlign": "right",
          "titleX": -8, "titleY": -2,  "titleFontSize": 10
        },
        {
          "orient": "top", "scale": "x",
          "ticks": false, "domain": false,
          "format": "%b", "formatType": "time",
          "labelAlign": "left",
          "encode": {
            "labels": {
              "update": {
                "x": {
                  "scale": "x", "field": "value", "band": 0,
                  "offset": {"signal": "month(datum.value) * offset"}
                },
                "opacity": {"signal": "date(datum.value) < 8 ? 1 : 0"}
              }
            }
          }
        }
      ],

      "marks": [
        {
          "type": "rect",
          "from": {"data": "values"},
          "encode": {
            "enter": {
              "x": {"scale": "x", "field": "w0", "offset": {"signal": "month(datum.date) * offset"}},
              "width": {"scale": "x", "band": 1, "offset": -1},
              "y": {"scale": "y", "field": "d0"},
              "height": {"scale": "y", "band": 1, "offset": -1},
              "cornerRadius": {"value": 2},
              "tooltip": {"signal": "timeFormat(datum.date, '%a %b %d, %Y') + '\\n' + format(datum.value, '+.2%')"}
            },
            "update": {
              "fill": {"scale": "color", "field": "value"}
            }
          }
        },
        {
          "type": "group",
          "name": "covid_annotation_group",
          "encode": {
            "enter": {
              "opacity": {"signal": "parent.year == 2020 ? 1 : 0"}
            }
          },
          "marks": [
            {
              "type": "rect",
              "encode": {
                "enter": {
                  "x": {
                    "signal": "scale('x', timeOffset('day', timeunit('yearweek', datetime(parent.year, 2, 1)))) + 2 * offset - 2"
                  },
                  "y": {"scale": "y", "value": "datetime(1900, 0, 0)", "offset": -2},
                  "x2": {
                    "signal": "scale('x', timeOffset('day', timeunit('yearweek', datetime(parent.year, 2, 31)))) + 2 * offset + scale('x', band: 1) + 2"
                  },
                  "y2": {"scale": "y", "value": "datetime(1900, 0, 6)", "offset": 2 + scale('y', band: 1)},
                  "fill": {"value": null},
                  "stroke": {"value": "red"},
                  "strokeWidth": {"value": 2},
                  "strokeDash": {"value": [4, 2]},
                  "cornerRadius": {"value": 4}
                }
              }
            },
            {
              "type": "text",
              "encode": {
                "enter": {
                  "x": {
                    "signal": "(scale('x', timeOffset('day', timeunit('yearweek', datetime(parent.year, 2, 1)))) + 2 * offset + scale('x', timeOffset('day', timeunit('yearweek', datetime(parent.year, 2, 31)))) + 2 * offset + scale('x', band: 1)) / 2"
                  },
                  "y": {"scale": "y", "value": "datetime(1900, 0, 0)", "offset": -20},
                  "align": {"value": "center"},
                  "baseline": {"value": "bottom"},
                  "text": {"value": "COVID-19 crash — Market fell ~34% in 23 trading days"},
                  "fill": {"value": "white"},
                  "fontWeight": {"value": "bold"},
                  "fontSize": {"value": 12},
                  "stroke": {"value": "black"},
                  "strokeWidth": {"value": 3},
                  "strokeOpacity": {"value": 0.7}
                }
              }
            }
          ]
        }
      ]
    }
  ]
}
