    {"name": "summerStart", "update": "scale('x', datetime(2000, 6, 1))"},   // July 1st (month 6 is July in 0-indexed months)
    {"name": "summerEnd", "update": "scale('x', datetime(2000, 7, 31))"}    // August 31st (month 7 is August)
  ],

  "data": [
    {
      "name": "temperature",
