        {"events": [{"signal": "mO"}], "update": "width+1"},
        {"events": [{"signal": "mO"}], "update": "width-1"},
        {"events": [{"signal": "tLO"}], "update": "width+1"},
        {"events": [{"signal": "tLO"}], "update": "width-1"},
        {"events": [{"signal": "sN"}], "update": "width+1"},
        {"events": [{"signal": "sN"}], "update": "width-1"},
        {"events": [{"signal": "mO"}], "update": "height+1"},
        {"events": [{"signal": "mO"}], "update": "height-1"},
        {"events": [{"signal": "tLO"}], "update": "height+1"},
        {"events": [{"signal": "tLO"}], "update": "height-1"}
      ]
