  "$schema": "https://vega.github.io/schema/vega/v6.json",
  "description": "A nested bar chart example, with bars grouped by category. Annotated with overall comparison across the three groups.",
  "width": 300,
  "padding": 5,
  "autosize": "pad",
  "signals": [
    {
      "name": "rangeStep",
      "value": 20,
      "bind": {
        "input": "range",
        "min": 5,
        "max": 50,
        "step": 1
      }
    },
    {
      "name": "innerPadding",
      "value": 0.1,
      "bind": {
        "input": "range",
        "min": 0,
        "max": 0.7,
        "step": 0.01
      }
    },
    {
      "name": "outerPadding",
      "value": 0.2,
      "bind": {
        "input": "range",
        "min": 0,
        "max": 0.4,
        "step": 0.01
      }
    },
    {
      "name": "height",
      "update": "trellisExtent[1]"
    }
  ],
  "data": [
    {
      "name": "tuples",
      "values": [
        {
          "a": 0,
          "b": "a",
          "c": 6.3
        },
        {
          "a": 0,
          "b": "a",
          "c": 4.2
        },
        {
          "a": 0,
          "b": "b",
          "c": 6.8
        },
        {
          "a": 0,
          "b": "c",
          "c": 5.1
        },
        {
          "a": 1,
          "b": "b",
          "c": 4.4
        },
        {
          "a": 2,
          "b": "b",
          "c": 3.5
        },
        {
          "a": 2,
          "b": "c",
          "c": 6.2
        }
      ],
      "transform": [
        {
          "type": "aggregate",
          "groupby": [
            "a",
            "b"
          ],
          "fields": [
            "c"
          ],
          "ops": [
            "average"
          ],
          "as": [
            "c"
          ]
        }
      ]
    },
