        {
          "type": "aggregate",
          "groupby": [
            "a"
          ]
        },
        {
          "type": "formula",
          "as": "span",
          "expr": "rangeStep * bandspace(datum.count, innerPadding, outerPadding)"
        },
        {
          "type": "stack",
          "field": "span"
        },
        {
          "type": "extent",
          "field": "y1",
          "signal": "trellisExtent"
        }
      ]
    },
    {
      "name": "group_summary",
      "source": "tuples",
      "transform": [
