      "transform": [
        {
          "type": "aggregate",
          "fields": [
            "mean_c"
          ],
          "ops": [
            "max",
            "min"
          ],
          "as": [
            "maxMean",
            "minMean"
          ]
        },
        {
          "type": "lookup",
          "from": "group_summary",
          "key": "rank",
          "fields": [
            1
          ],
          "values": [
            "a",
            "mean_c"
          ],
          "as": [
            "topGroup",
            "topMean"
          ]
        },
        {
          "type": "lookup",
          "from": "group_summary",
          "key": "rank",
          "fields": [
            2
          ],
          "values": [
