        {
          "type": "aggregate",
          "groupby": ["variety"],
          "fields": ["yield", "yield", "yield", "yield", "yield", "yield", "yield"],
          "ops": ["mean", "stdev", "stderr", "ci0", "ci1", "q1", "q3"],
          "as": ["mean", "stdev", "stderr", "ci0", "ci1", "iqr0", "iqr1"]
        },
        {
          "type": "formula",
          "as": "stdev0",
          "expr": "datum.mean - datum.stdev"
        },
        {
          "type": "formula",
          "as": "stdev1",
          "expr": "datum.mean + datum.stdev"
        },
        {
          "type": "formula",
          "as": "stderr0",
          "expr": "datum.mean - datum.stderr"
        },
        {
          "type": "formula",
          "as": "stderr1",
