{
  "$schema": "https://vega.github.io/schema/vega/v6.json",
  "description": "A histogram of film ratings, modified to include null values, with an annotation highlighting missing data.",
  "width": 400,
  "height": 200,
  "padding": 5,
  "autosize": { "type": "fit", "resize": true },

  "signals": [
    {
      "name": "maxbins",
      "value": 10,
      "bind": { "input": "select", "options": [5, 10, 20] }
    },
    {
      "name": "binCount",
      "update": "(bins.stop - bins.start) / bins.step"
    },
    { "name": "nullGap", "value": 10 },
    {
      "name": "barStep",
      "update": "(width - nullGap) / (1 + binCount)"
    },

    {
      "name": "nullBarX",
      "update": "scale('xscale-null', null) + 1"
    },
    {
      "name": "nullBarX2",
      "update": "scale('xscale-null', null) + scale('xscale-null', null, {band: 1})"
    },
    {
      "name": "nullBarCenterX",
      "update": "(nullBarX + nullBarX2) / 2"
    },
    {
      "name": "nullBarTopY",
      "update": "scale('yscale', data('nulls')[0] ? data('nulls')[0].count : 0)"
    },

    {
      "name": "annotX",
      "value": 140
    },
    {
      "name": "annotY",
      "value": 30
    }
  ],

  "data": [
    {
      "name": "table",
      "url": "data/movies.json",
      "transform": [
        { "type": "extent", "field": "IMDB Rating", "signal": "extent" },
        {
          "type": "bin",
          "signal": "bins",
          "field": "IMDB Rating",
          "extent": { "signal": "extent" },
          "maxbins": { "signal": "maxbins" }
        }
      ]
    },
    {
      "name": "counts",
      "source": "table",
      "transform": [
        { "type": "filter", "expr": "datum['IMDB Rating'] != null" },
        { "type": "aggregate", "groupby": ["bin0", "bin1"] }
      ]
    },
    {
      "name": "nulls",
      "source": "table",
      "transform": [
        { "type": "filter", "expr": "datum['IMDB Rating'] == null" },
        { "type": "aggregate" }
      ]
    }
  ],

  "scales": [
    {
      "name": "yscale",
      "type": "linear",
      "range": "height",
      "round": true,
      "nice": true,
      "domain": {
        "fields": [
          { "data": "counts", "field": "count" },
          { "data": "nulls", "field": "count" }
        ]
      }
    },
    {
      "name": "xscale",
      "type": "linear",
      "range": [{ "signal": "barStep + nullGap" }, { "signal": "width" }],
      "round": true,
      "domain": { "signal": "[bins.start, bins.stop]" },
      "bins": { "signal": "bins" }
    },
    {
      "name": "xscale-null",
      "type": "band",
      "range": [0, { "signal": "barStep" }],
      "round": true,
      "domain": [null]
    }
  ],

  "axes": [
    { "orient": "bottom", "scale": "xscale", "tickMinStep": 0.5 },
    { "orient": "bottom", "scale": "xscale-null" },
    { "orient": "left", "scale": "yscale", "tickCount": 5, "offset": 5 }
  ],

  "marks": [
    {
      "type": "rect",
      "from": { "data": "counts" },
      "encode": {
        "update": {
          "x": { "scale": "xscale", "field": "bin0", "offset": 1 },
          "x2": { "scale": "xscale", "field": "bin1" },
          "y": { "scale": "yscale", "field": "count" },
          "y2": { "scale": "yscale", "value": 0 },
          "fill": { "value": "steelblue" }
        },
        "hover": { "fill": { "value": "firebrick" } }
      }
    },
    {
      "type": "rect",
      "from": { "data": "nulls" },
      "encode": {
        "update": {
          "x": { "scale": "xscale-null", "value": null, "offset": 1 },
          "x2": { "scale": "xscale-null", "band": 1 },
          "y": { "scale": "yscale", "field": "count" },
          "y2": { "scale": "yscale", "value": 0 },
          "fill": { "value": "#aaa" }
        },
        "hover": { "fill": { "value": "firebrick" } }
      }
    },

    {
      "type": "group",
      "name": "missing-annotation",
      "encode": {
        "update": {
          "x": { "value": 0 },
          "y": { "value": 0 },
          "width": { "signal": "width" },
          "height": { "signal": "height" }
        }
      },
      "marks": [
        {
          "type": "symbol",
          "name": "null-circle",
          "encode": {
            "update": {
              "x": { "signal": "nullBarCenterX" },
              "y": { "signal": "nullBarTopY / 2" },
              "size": { "signal": "pow(max(18, (nullBarX2 - nullBarX) + 14), 2)" },
              "shape": { "value": "circle" },
              "fill": { "value": null },
              "stroke": { "value": "#666" },
              "strokeWidth": { "value": 2 }
            }
          }
        },
        {
          "type": "text",
          "name": "missing-text",
          "encode": {
            "update": {
              "x": { "signal": "annotX" },
              "y": { "signal": "annotY" },
              "text": { "value": "Missing Data (~200 films)" },
              "fontSize": { "value": 12 },
              "fill": { "value": "#333" },
              "align": { "value": "left" },
              "baseline": { "value": "middle" }
            }
          }
        },
        {
          "type": "path",
          "name": "missing-arrow",
          "encode": {
            "update": {
              "path": {
                "signal": "'M' + annotX + ',' + annotY + ' L' + (nullBarCenterX + 2) + ',' + (nullBarTopY * 0.6)"
