        },
        { "type": "geopath", "projection": "projection" },
        { "type": "formula", "as": "centroid", "expr": "pathCentroid(datum.path)" }
      ]
    }
  ],
  "marks": [
    {
      "type": "shape",
      "from": { "data": "graticule" },
      "encode": {
        "enter": {
          "strokeWidth": { "value": 1 },
          "stroke": { "value": "#ddd" },
          "fill": { "value": null }
        }
      },
      "transform": [{ "type": "geoshape", "projection": "projection" }]
    },
    {
      "type": "shape",
      "from": { "data": "world" },
      "encode": {
        "enter": {
          "strokeWidth": { "value": 0.5 },
          "stroke": { "value": "#bbb" },
          "fill": { "value": "#e5e8d3" }
        }
      },
      "transform": [{ "type": "geoshape", "projection": "projection" }]
    },
    {
      "name": "largest_country_outline",
      "type": "shape",
      "from": { "data": "largest_country" },
      "encode": {
        "enter": {
