          "as": ["a0", "r0", "a1", "r1", "depth", "children"]
        }
      ]
    },
    {
      "name": "dominant",
      "source": "tree",
      "transform": [
        {
          "type": "formula",
          "as": "angleSpan",
          "expr": "datum.a1 - datum.a0"
        },
        {
          "type": "collect",
          "sort": { "field": "angleSpan", "order": "descending" }
        },
        { "type": "limit", "count": 1 },
        {
          "type": "formula",
          "as": "midAngle",
          "expr": "(datum.a0 + datum.a1) / 2"
        },
        {
          "type": "formula",
          "as": "midRadius",
          "expr": "(datum.r0 + datum.r1) / 2"
        },
        {
          "type": "formula",
          "as": "labelRadius",
          "expr": "datum.r1 + 18"
        },
        {
          "type": "formula",
          "as": "cx",
          "expr": "width / 2"
        },
        {
          "type": "formula",
          "as": "cy",
          "expr": "height / 2"
        },
        {
          "type": "formula",
          "as": "xArc",
          "expr": "width/2 + cos(datum.midAngle - PI/2) * datum.midRadius"
        },
        {
          "type": "formula",
          "as": "yArc",
          "expr": "height/2 + sin(datum.midAngle - PI/2) * datum.midRadius"
        },
        {
          "type": "formula",
          "as": "xLabel",
          "expr": "width/2 + cos(datum.midAngle - PI/2) * datum.labelRadius"
        },
        {
          "type": "formula",
          "as": "yLabel",
          "expr": "height/2 + sin(datum.midAngle - PI/2) * datum.labelRadius"
        },
        {
          "type": "formula",
          "as": "labelAlign",
          "expr": "cos(datum.midAngle - PI/2) >= 0 ? 'left' : 'right'"
        },
        {
          "type": "formula",
          "as": "labelDx",
          "expr": "cos(datum.midAngle - PI/2) >= 0 ? 6 : -6"
        }
      ]
    }
  ],

