      "name": "sourceDegree",
      "source": "edges",
      "transform": [{"type": "aggregate", "groupby": ["source"]}]
    },
    {
      "name": "targetDegree",
      "source": "edges",
      "transform": [{"type": "aggregate", "groupby": ["target"]}]
    },
    {
      "name": "nodes",
      "url": "data/miserables.json",
      "format": {"type": "json", "property": "nodes"},
      "transform": [
        {"type": "window", "ops": ["rank"], "as": ["order"]},
        {
          "type": "lookup",
          "from": "sourceDegree",
          "key": "source",
          "fields": ["index"],
          "as": ["sourceDegree"],
          "default": {"count": 0}
        },
        {
          "type": "lookup",
          "from": "targetDegree",
          "key": "target",
          "fields": ["index"],
          "as": ["targetDegree"],
          "default": {"count": 0}
        },
        {
          "type": "formula",
          "as": "degree",
          "expr": "datum.sourceDegree.count + datum.targetDegree.count"
        }
      ]
    },

    {
      "name": "selectedNodes",
      "source": "nodes",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.name === characterA || datum.name === characterB"
        }
      ]
    },

    {
      "name": "edgesWithNames",
      "source": "edges",
      "transform": [
        {
          "type": "lookup",
          "from": "nodes",
          "key": "index",
          "fields": ["source"],
          "as": ["sourceNode"],
          "default": null
        },
        {
          "type": "lookup",
          "from": "nodes",
          "key": "index",
          "fields": ["target"],
          "as": ["targetNode"],
          "default": null
        },
        {"type": "formula", "as": "sourceName", "expr": "datum.sourceNode ? datum.sourceNode.name : null"},
        {"type": "formula", "as": "targetName", "expr": "datum.targetNode ? datum.targetNode.name : null"},
        {
          "type": "formula",
          "as": "isA",
          "expr": "datum.sourceName === characterA || datum.targetName === characterA"
        },
        {
          "type": "formula",
          "as": "isB",
          "expr": "datum.sourceName === characterB || datum.targetName === characterB"
        },
        {
          "type": "formula",
          "as": "isAB",
          "expr": "(datum.sourceName === characterA && datum.targetName === characterB) || (datum.sourceName === characterB && datum.targetName === characterA)"
        }
      ]
    },

    {
      "name": "neighborsA",
      "source": "edgesWithNames",
      "transform": [
        {"type": "filter", "expr": "datum.isA"},
