          "expr": "datum.sourceName === characterA ? datum.targetName : datum.sourceName"
        },
        {"type": "aggregate", "groupby": ["neighbor"], "ops": ["sum"], "fields": ["value"], "as": ["weightA"]},
        {"type": "window", "sort": {"field": "weightA", "order": "descending"}, "ops": ["rank"], "as": ["rankA"]},
        {"type": "filter", "expr": "datum.rankA <= topK"}
      ]
    },
    {
      "name": "neighborsB",
      "source": "edgesWithNames",
      "transform": [
        {"type": "filter", "expr": "datum.isB"},
