          "type": "formula",
          "as": "neighbor",
          "expr": "datum.sourceName === characterB ? datum.targetName : datum.sourceName"
        },
        {"type": "aggregate", "groupby": ["neighbor"], "ops": ["sum"], "fields": ["value"], "as": ["weightB"]},
        {"type": "window", "sort": {"field": "weightB", "order": "descending"}, "ops": ["rank"], "as": ["rankB"]},
