      "transform": [
        {
          "type": "lookup",
          "from": "neighborsB",
          "key": "neighbor",
          "fields": ["neighbor"],
          "as": ["bRow"],
          "default": null
        },
        {"type": "formula", "as": "weightB", "expr": "datum.bRow ? datum.bRow.weightB : 0"},
        {"type": "formula", "as": "shared", "expr": "datum.weightA > 0 && datum.weightB > 0"},
        {"type": "formula", "as": "diff", "expr": "datum.weightA - datum.weightB"}
      ]
    },
    {
      "name": "neighborComparisonBOnly",
      "source": "neighborsB",
      "transform": [
        {
          "type": "lookup",
          "from": "neighborsA",
          "key": "neighbor",
          "fields": ["neighbor"],
          "as": ["aRow"],
          "default": null
        },
        {"type": "filter", "expr": "!datum.aRow"},
        {"type": "formula", "as": "weightA", "expr": "0"},
        {"type": "formula", "as": "shared", "expr": "false"},
        {"type": "formula", "as": "diff", "expr": "0 - datum.weightB"}
      ]
    },
    {
      "name": "neighborComparisonAll",
      "source": "neighborComparison",
      "transform": [
        {
          "type": "collect",
          "sort": {"field": "shared", "order": "descending"}
        }
      ]
    },
    {
      "name": "neighborComparisonAll2",
      "source": "neighborComparisonAll",
      "transform": [
        {
          "type": "union",
          "fields": ["neighbor", "weightA", "weightB", "shared", "diff"],
          "as": ["neighbor", "weightA", "weightB", "shared", "diff"],
          "from": "neighborComparisonBOnly"
        }
      ]
    },

    {
      "name": "summary",
      "source": "edgesWithNames",
      "transform": [
        {
          "type": "aggregate",
          "ops": ["sum", "sum", "sum"],
          "fields": ["value", "value", "value"],
          "as": ["sumA", "sumB", "sumAB"],
          "groupby": []
        },
        {
          "type": "formula",
          "as": "sumA",
          "expr": "sum(filter(data('edgesWithNames'), d => d.isA).map(d => d.value))"
        },
        {
          "type": "formula",
          "as": "sumB",
          "expr": "sum(filter(data('edgesWithNames'), d => d.isB).map(d => d.value))"
        },
        {
          "type": "formula",
          "as": "sumAB",
          "expr": "sum(filter(data('edgesWithNames'), d => d.isAB).map(d => d.value))"
        }
      ]
    }
  ],

  "scales": [
    {
      "name": "position",
      "type": "band",
      "domain": {"data": "nodes", "field": "order", "sort": true},
      "range": "width"
    },
    {
      "name": "color",
      "type": "ordinal",
      "range": "category",
      "domain": {"data": "nodes", "field": "group"}
    },
    {
      "name": "compareColor",
      "type": "ordinal",
      "domain": ["A", "B", "Shared"],
      "range": ["#1f77b4", "#ff7f0e", "#2ca02c"]
    }
  ],

  "legends": [
    {
      "fill": "compareColor",
      "title": "Connection type (selected characters)",
      "orient": "top-right"
    }
  ],

  "marks": [
    {
      "type": "group",
      "name": "arcDiagram",
      "encode": {
        "enter": {
          "x": {"value": 0},
          "y": {"value": 0},
          "width": {"signal": "width"},
          "height": {"signal": "height"}
        }
      },
      "marks": [
        {
          "type": "symbol",
          "name": "layout",
          "interactive": false,
          "from": {"data": "nodes"},
          "encode": {
            "enter": {"opacity": {"value": 0}},
            "update": {
              "x": {"scale": "position", "field": "order"},
              "y": {"signal": "baselineY"},
              "size": {"field": "degree", "mult": 5, "offset": 10},
              "fill": {"scale": "color", "field": "group"}
            }
          }
        },
        {
          "type": "path",
          "name": "allLinks",
          "from": {"data": "edges"},
          "encode": {
            "update": {
              "stroke": {"value": "#000"},
              "strokeOpacity": {"value": 0.12},
              "strokeWidth": {"field": "value"}
            }
          },
          "transform": [
            {
              "type": "lookup",
              "from": "layout",
              "key": "datum.index",
              "fields": ["datum.source", "datum.target"],
              "as": ["sourceNode", "targetNode"]
            },
            {
              "type": "linkpath",
              "sourceX": {"expr": "min(datum.sourceNode.x, datum.targetNode.x)"},
              "targetX": {"expr": "max(datum.sourceNode.x, datum.targetNode.x)"},
              "sourceY": {"signal": "baselineY"},
              "targetY": {"signal": "baselineY"},
              "shape": "arc"
            }
          ]
        },
        {
          "type": "path",
          "name": "highlightLinks",
          "from": {"data": "edgesWithNames"},
          "encode": {
            "update": {
              "stroke": {
                "signal": "datum.isAB ? scale('compareColor','Shared') : (datum.isA ? scale('compareColor','A') : (datum.isB ? scale('compareColor','B') : '#000'))"
              },
              "strokeOpacity": {
                "signal": "datum.isAB ? 0.9 : (datum.isA || datum.isB ? 0.55 : 0)"
              },
              "strokeWidth": {
                "signal": "datum.isAB ? max(2, datum.value) : (datum.isA || datum.isB ? max(1.5, datum.value) : 0)"
              }
            }
          },
          "transform": [
            {
              "type": "lookup",
              "from": "layout",
              "key": "datum.index",
              "fields": ["datum.source", "datum.target"],
              "as": ["sourceNode", "targetNode"]
            },
            {
              "type": "linkpath",
              "sourceX": {"expr": "min(datum.sourceNode.x, datum.targetNode.x)"},
              "targetX": {"expr": "max(datum.sourceNode.x, datum.targetNode.x)"},
              "sourceY": {"signal": "baselineY"},
              "targetY": {"signal": "baselineY"},
              "shape": "arc"
            }
          ]
        },
        {
          "type": "symbol",
          "name": "nodeMarks",
          "from": {"data": "layout"},
          "encode": {
            "update": {
              "x": {"field": "x"},
              "y": {"field": "y"},
              "fill": {"field": "fill"},
              "size": {"field": "size"},
              "stroke": {
                "signal": "(datum.datum && (datum.datum.name === characterA || datum.datum.name === characterB)) ? '#111' : null"
              },
              "strokeWidth": {
                "signal": "(datum.datum && (datum.datum.name === characterA || datum.datum.name === characterB)) ? 2 : 0"
              }
            }
          }
        },
        {
          "type": "text",
          "name": "nodeLabels",
          "from": {"data": "nodes"},
          "encode": {
            "update": {
              "x": {"scale": "position", "field": "order"},
              "y": {"signal": "baselineY + 12"},
              "fontSize": {"value": 9},
              "align": {"value": "right"},
              "baseline": {"value": "middle"},
              "angle": {"value": -90},
              "fill": {
                "signal": "(datum.name === characterA) ? scale('compareColor','A') : ((datum.name === characterB) ? scale('compareColor','B') : '#333')"
              },
              "fontWeight": {
                "signal": "(datum.name === characterA || datum.name === characterB) ? 'bold' : 'normal'"
              },
              "text": {"field": "name"}
            }
          }
        }
      ]
    },

    {
      "type": "group",
      "name": "annotationPanel",
      "encode": {
        "enter": {
          "x": {"value": 0},
          "y": {"value": 0},
          "width": {"signal": "width"},
          "height": {"value": 120}
        }
      },
      "marks": [
        {
          "type": "text",
          "encode": {
            "enter": {
              "x": {"value": 0},
              "y": {"value": 14},
              "fontSize": {"value": 12},
              "fontWeight": {"value": "bold"},
              "text": {"signal": "'Compare connection patterns: ' + characterA + ' vs ' + characterB"}
            }
          }
        },
        {
          "type": "text",
          "from": {"data": "summary"},
          "encode": {
            "enter": {
              "x": {"value": 0},
              "y": {"value": 34},
              "fontSize": {"value": 11},
              "fill": {"value": "#333"},
              "text": {
                "signal": "'Total link weight — ' + characterA + ': ' + format(datum.sumA, ',') + ' | ' + characterB + ': ' + format(datum.sumB, ',') + ' | Between them: ' + format(datum.sumAB, ',')"
              }
            }
          }
        },

        {
          "type": "group",
          "name": "comparisonTable",
          "encode": {
            "enter": {
              "x": {"value": 0},
              "y": {"value": 50},
              "width": {"signal": "width"},
              "height": {"value": 70}
            }
          },
          "marks": [
            {
              "type": "text",
              "encode": {
                "enter": {
                  "x": {"value": 0},
                  "y": {"value": 0},
                  "fontSize": {"value": 10},
                  "fontWeight": {"value": "bold"},
                  "fill": {"value": "#333"},
                  "text": {"signal": "'Top neighbors (by weight). Green = shared; Blue = stronger for ' + characterA + '; Orange = stronger for ' + characterB"}
                }
              }
            },
            {
              "type": "text",
              "from": {"data": "neighborComparisonAll2"},
              "encode": {
                "update": {
                  "x": {"value": 0},
                  "y": {"field": "rankA", "mult": 12, "offset": 16},
                  "fontSize": {"value": 10},
                  "fill": {
                    "signal": "datum.shared ? scale('compareColor','Shared') : (datum.diff >= 0 ? scale('compareColor','A') : scale('compareColor','B'))"
                  },
                  "text": {
                    "signal": "datum.neighbor + ' — ' + characterA + ': ' + format(datum.weightA, ',') + ' | ' + characterB + ': ' + format(datum.weightB, ',')"
                  }
                }
              }
            }
          ]
        }
      ]
    }
  ]
}
