{
  "$schema": "https://vega.github.io/schema/vega/v6.json",
  "description": "Interactive map of U.S. airport connections in 2008, annotated with hub density differences between eastern and western halves.",
  "width": 900,
  "height": 560,
  "padding": { "top": 25, "left": 0, "right": 0, "bottom": 0 },
  "autosize": "none",

  "signals": [
    {
      "name": "scale",
      "value": 1200,
      "bind": { "input": "range", "min": 500, "max": 3000 }
    },
    {
      "name": "translateX",
      "value": 450,
      "bind": { "input": "range", "min": -500, "max": 1200 }
    },
    {
      "name": "translateY",
      "value": 260,
      "bind": { "input": "range", "min": -300, "max": 700 }
    },
    {
      "name": "shape",
      "value": "line",
      "bind": { "input": "radio", "options": ["line", "curve"] }
    },
    {
      "name": "hover",
      "value": null,
      "on": [
        { "events": "@cell:pointerover", "update": "datum" },
        { "events": "@cell:pointerout", "update": "null" }
      ]
    },
    {
      "name": "title",
      "value": "U.S. Airports, 2008",
      "update": "hover ? hover.name + ' (' + hover.iata + ')' : 'U.S. Airports, 2008'"
    },
    {
      "name": "cell_stroke",
      "value": null,
      "on": [
        { "events": "dblclick", "update": "cell_stroke ? null : 'brown'" },
        { "events": "pointerdown!", "update": "cell_stroke" }
      ]
    },

    {
      "name": "splitLon",
      "value": -95,
      "bind": { "input": "range", "min": -125, "max": -65, "step": 1 }
    },
    {
      "name": "hubThreshold",
      "value": 20000,
      "bind": { "input": "range", "min": 1000, "max": 60000, "step": 1000 }
    },
    {
      "name": "eastLabel",
      "update": "'East (lon ≥ ' + splitLon + '°): ' + format(data('hub_summary')[0].eastHubs, ',') + ' hubs / ' + format(data('hub_summary')[0].eastAirports, ',') + ' airports (' + format(100*data('hub_summary')[0].eastDensity, '.1f') + '%)';"
    },
    {
      "name": "westLabel",
      "update": "'West (lon < ' + splitLon + '°): ' + format(data('hub_summary')[0].westHubs, ',') + ' hubs / ' + format(data('hub_summary')[0].westAirports, ',') + ' airports (' + format(100*data('hub_summary')[0].westDensity, '.1f') + '%)';"
    },
    {
      "name": "diffLabel",
      "update": "'Density difference (East − West): ' + format(100*(data('hub_summary')[0].eastDensity - data('hub_summary')[0].westDensity), '+.1f') + ' pp';"
    }
  ],

  "data": [
    {
      "name": "states",
      "url": "data/us-10m.json",
      "format": { "type": "topojson", "feature": "states" },
      "transform": [
        {
          "type": "geopath",
          "projection": "projection"
        }
      ]
    },
    {
      "name": "traffic",
      "url": "data/flights-airport.csv",
      "format": { "type": "csv", "parse": "auto" },
      "transform": [
        {
          "type": "aggregate",
          "groupby": ["origin"],
          "fields": ["count"],
          "ops": ["sum"],
          "as": ["flights"]
        }
      ]
    },
    {
      "name": "airports",
      "url": "data/airports.csv",
      "format": { "type": "csv", "parse": "auto" },
      "transform": [
        {
          "type": "lookup",
          "from": "traffic",
          "key": "origin",
          "fields": ["iata"],
          "as": ["traffic"]
        },
        {
          "type": "filter",
          "expr": "datum.traffic != null"
        },
        {
          "type": "formula",
          "as": "side",
          "expr": "datum.longitude >= splitLon ? 'East' : 'West'"
        },
        {
          "type": "formula",
          "as": "isHub",
          "expr": "datum.traffic && datum.traffic.flights >= hubThreshold"
        },
        {
          "type": "geopoint",
          "projection": "projection",
          "fields": ["longitude", "latitude"]
        },
        {
          "type": "filter",
          "expr": "datum.x != null && datum.y != null"
        },
        {
          "type": "voronoi",
          "x": "x",
          "y": "y"
        },
        {
          "type": "collect",
          "sort": {
            "field": "traffic.flights",
            "order": "descending"
          }
        }
      ]
    },
    {
