          "as": "eastHubs",
          "expr": "sum(pluck(filter(data('airports'), 'datum.side==\\'East\\''), 'isHub'))"
        },
        {
          "type": "formula",
          "as": "eastAirports",
          "expr": "length(filter(data('airports'), 'datum.side==\\'East\\''))"
        },
        {
          "type": "formula",
          "as": "westHubs",
          "expr": "sum(pluck(filter(data('airports'), 'datum.side==\\'West\\''), 'isHub'))"
        },
        {
          "type": "formula",
          "as": "westAirports",
          "expr": "length(filter(data('airports'), 'datum.side==\\'West\\''))"
        },
        {
          "type": "formula",
          "as": "eastDensity",
          "expr": "datum.eastAirports > 0 ? datum.eastHubs / datum.eastAirports : 0"
        },
        {
          "type": "formula",
          "as": "westDensity",
          "expr": "datum.westAirports > 0 ? datum.westHubs / datum.westAirports : 0"
        }
      ]
    },
    {
