      "value": "line",
      "bind": { "input": "radio", "options": ["line", "curve"] }
    },
    {
      "name": "hover",
      "value": null,
      "on": [
        { "events": "@cell:pointerover", "update": "datum" },
        { "events": "@cell:pointerout", "update": "null" }
      ]
    },
    {
      "name": "title",
      "value": "U.S. Airports, 2008",
      "update": "hover ? hover.name + ' (' + hover.iata + ')' : 'U.S. Airports, 2008'"
    },
    {
      "name": "cell_stroke",
      "value": null,
      "on": [
        { "events": "dblclick", "update": "cell_stroke ? null : 'brown'" },
        { "events": "pointerdown!", "update": "cell_stroke" }
      ]
    }
  ],

  "data": [
    {
      "name": "states",
      "url": "data/us-10m.json",
      "format": { "type": "topojson", "feature": "states" },
      "transform": [
        { "type": "geopath", "projection": "projection" }
      ]
    },
    {
      "name": "traffic",
      "url": "data/flights-airport.csv",
      "format": { "type": "csv", "parse": "auto" },
      "transform": [
        {
          "type": "aggregate",
          "groupby": ["origin"],
          "fields": ["count"],
          "ops": ["sum"],
          "as": ["flights"]
        }
      ]
    },
    {
      "name": "airports",
      "url": "data/airports.csv",
      "format": { "type": "csv", "parse": "auto" },
      "transform": [
        {
          "type": "lookup",
          "from": "traffic",
          "key": "origin",
          "fields": ["iata"],
          "as": ["traffic"]
        },
        { "type": "filter", "expr": "datum.traffic != null" },
        {
          "type": "geopoint",
          "projection": "projection",
          "fields": ["longitude", "latitude"]
        },
        { "type": "filter", "expr": "datum.x != null && datum.y != null" },
        { "type": "voronoi", "x": "x", "y": "y" },
        {
          "type": "collect",
          "sort": { "field": "traffic.flights", "order": "descending" }
        }
      ]
    },
    {
      "name": "routes",
      "url": "data/flights-airport.csv",
      "format": { "type": "csv", "parse": "auto" },
      "transform": [
        { "type": "filter", "expr": "hover && hover.iata == datum.origin" },
        {
          "type": "lookup",
          "from": "airports",
          "key": "iata",
          "fields": ["origin", "destination"],
          "as": ["source", "target"]
        },
        { "type": "filter", "expr": "datum.source && datum.target" },
        { "type": "linkpath", "shape": { "signal": "shape" } }
      ]
    },

    {
      "name": "key_airports",
      "source": "airports",
      "transform": [
        { "type": "filter", "expr": "datum.iata === 'DEN' || datum.iata === 'SLC'" }
      ]
    },
    {
      "name": "annotation_points",
      "values": [
        {
          "id": "note",
          "label": "Sparse coverage in the Mountain & Plains states reflects lower population density and fewer airports in this dataset; long-distance connections often funnel through major hubs.",
          "x": 520,
          "y": 210
        },
        { "id": "DEN", "label": "Denver (DEN)", "x": 610, "y": 300 },
        { "id": "SLC", "label": "Salt Lake City (SLC)", "x": 520, "y": 330 }
      ]
    },
    {
      "name": "annotation_links",
      "source": "key_airports",
      "transform": [
        {
          "type": "lookup",
          "from": "annotation_points",
          "key": "id",
          "fields": ["iata"],
          "as": ["ann"]
        },
        { "type": "filter", "expr": "datum.ann != null" },
        {
          "type": "formula",
          "as": "x1",
          "expr": "datum.ann.x"
        },
        {
          "type": "formula",
          "as": "y1",
          "expr": "datum.ann.y"
        },
        {
          "type": "formula",
          "as": "x2",
          "expr": "datum.x"
        },
        {
          "type": "formula",
          "as": "y2",
          "expr": "datum.y"
        }
      ]
    }
  ],

  "projections": [
    {
      "name": "projection",
      "type": "albersUsa",
      "scale": { "signal": "scale" },
      "translate": [{ "signal": "translateX" }, { "signal": "translateY" }]
    }
  ],

  "scales": [
    {
      "name": "size",
      "type": "linear",
      "domain": { "data": "traffic", "field": "flights" },
      "range": [16, 1000]
    }
  ],

  "marks": [
    {
      "type": "path",
      "from": { "data": "states" },
      "encode": {
        "enter": {
          "fill": { "value": "#dedede" },
          "stroke": { "value": "white" }
        },
        "update": { "path": { "field": "path" } }
      }
    },
    {
      "type": "symbol",
      "from": { "data": "airports" },
      "encode": {
        "enter": {
          "size": { "scale": "size", "field": "traffic.flights" },
          "fill": { "value": "steelblue" },
          "fillOpacity": { "value": 0.8 },
          "stroke": { "value": "white" },
          "strokeWidth": { "value": 1.5 }
        },
        "update": {
          "x": { "field": "x" },
          "y": { "field": "y" }
        }
      }
    },
    {
      "type": "path",
      "name": "cell",
      "from": { "data": "airports" },
      "encode": {
        "enter": {
          "fill": { "value": "transparent" },
          "strokeWidth": { "value": 0.35 }
        },
        "update": {
          "path": { "field": "path" },
          "stroke": { "signal": "cell_stroke" }
        }
      }
    },
    {
      "type": "path",
      "interactive": false,
      "from": { "data": "routes" },
      "encode": {
        "enter": {
          "path": { "field": "path" },
          "stroke": { "value": "black" },
          "strokeOpacity": { "value": 0.35 }
        }
      }
    },

    {
      "type": "path",
      "interactive": false,
      "from": { "data": "annotation_links" },
      "encode": {
        "enter": {
          "stroke": { "value": "#333" },
          "strokeWidth": { "value": 1.5 },
          "fill": { "value": null }
        },
        "update": {
          "path": { "signal": "path({x: datum.x1, y: datum.y1}, {x: datum.x2, y: datum.y2})" }
        }
      }
    },
    {
      "type": "symbol",
      "interactive": false,
      "from": { "data": "annotation_links" },
      "encode": {
        "enter": {
          "shape": { "value": "triangle-right" },
          "size": { "value": 90 },
          "fill": { "value": "#333" }
        },
        "update": {
          "x": { "field": "x2" },
          "y": { "field": "y2" },
          "angle": { "signal": "atan2(datum.y2 - datum.y1, datum.x2 - datum.x1) * 180 / PI" }
        }
      }
    },

    {
      "type": "text",
      "interactive": false,
      "from": { "data": "annotation_points" },
