          "y": { "field": "y" },
          "text": { "field": "label" },
          "limit": { "value": 320 }
        }
      }
    },
    {
      "type": "text",
      "interactive": false,
      "from": { "data": "annotation_points" },
      "transform": [{ "type": "filter", "expr": "datum.id === 'DEN' || datum.id === 'SLC'" }],
      "encode": {
        "enter": {
          "fill": { "value": "#111" },
          "fontSize": { "value": 12 },
          "fontWeight": { "value": "bold" },
          "align": { "value": "left" },
          "baseline": { "value": "middle" }
        },
        "update": {
          "x": { "field": "x" },
          "y": { "field": "y" },
          "text": { "field": "label" }
        }
      }
    },

    {
      "type": "text",
      "interactive": false,
      "encode": {
        "enter": {
          "x": { "value": 895 },
          "y": { "value": 0 },
          "fill": { "value": "black" },
          "fontSize": { "value": 20 },
          "align": { "value": "right" }
        },
        "update": { "text": { "signal": "title" } }
      }
    }
  ]
}
