          "as": "isInteractiveTheme",
          "expr": "indexof(['INTERACTION','INTERACTIVE','SELECTIONS','EVENT','REACTIVE'], datum.text) >= 0"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "color",
      "type": "ordinal",
