{
  "$schema": "https://vega.github.io/schema/vega/v6.json",
  "description": "An interactive scatter plot of global health statistics by country and year. Highlights an outlier in 1980 (Sub-Saharan Africa) with very high fertility and very low life expectancy.",
  "width": 800,
  "height": 600,
  "padding": 5,
  "data": [
    {
      "name": "gapminder",
      "url": "data/gapminder.json"
    },
    {
      "name": "clusters",
      "values": [
        { "id": 0, "name": "South Asia" },
        { "id": 1, "name": "Europe & Central Asia" },
        { "id": 2, "name": "Sub-Saharan Africa" },
        { "id": 3, "name": "America" },
        { "id": 4, "name": "East Asia & Pacific" },
        { "id": 5, "name": "Middle East & North Africa" }
      ]
    },
    {
      "name": "country_timeline",
      "source": "gapminder",
      "transform": [
        { "type": "filter", "expr": "timeline && datum.country == timeline.country" },
        { "type": "collect", "sort": { "field": "year" } }
      ]
    },
    {
      "name": "thisYear",
      "source": "gapminder",
      "transform": [
        { "type": "filter", "expr": "datum.year == currentYear" }
      ]
    },
    {
      "name": "prevYear",
      "source": "gapminder",
      "transform": [
        { "type": "filter", "expr": "datum.year == currentYear - stepYear" }
      ]
    },
    {
      "name": "nextYear",
      "source": "gapminder",
      "transform": [
        { "type": "filter", "expr": "datum.year == currentYear + stepYear" }
      ]
    },
    {
      "name": "countries",
      "source": "gapminder",
      "transform": [
        { "type": "aggregate", "groupby": [ "country" ] }
      ]
    },
    {
      "name": "interpolate",
      "source": "countries",
      "transform": [
        {
          "type": "lookup",
          "from": "thisYear",
          "key": "country",
          "fields": [ "country" ],
          "as": [ "this" ],
          "default": {}
        },
        {
          "type": "lookup",
          "from": "prevYear",
          "key": "country",
          "fields": [ "country" ],
          "as": [ "prev" ],
          "default": {}
        },
        {
          "type": "lookup",
          "from": "nextYear",
          "key": "country",
          "fields": [ "country" ],
          "as": [ "next" ],
          "default": {}
        },
        {
          "type": "formula",
          "as": "target_fertility",
          "expr": "interYear > currentYear ? datum.next.fertility : (datum.prev.fertility||datum.this.fertility)"
        },
        {
          "type": "formula",
          "as": "target_life_expect",
          "expr": "interYear > currentYear ? datum.next.life_expect : (datum.prev.life_expect||datum.this.life_expect)"
        },
        {
          "type": "formula",
          "as": "inter_fertility",
          "expr": "interYear==2000 ? datum.this.fertility : datum.this.fertility + (datum.target_fertility-datum.this.fertility) * abs(interYear-datum.this.year)/5"
        },
        {
          "type": "formula",
          "as": "inter_life_expect",
          "expr": "interYear==2000 ? datum.this.life_expect : datum.this.life_expect + (datum.target_life_expect-datum.this.life_expect) * abs(interYear-datum.this.year)/5"
        },
        {
          "type": "formula",
          "as": "isOutlier1980",
          "expr": "currentYear==1980 && datum.this && datum.this.cluster==2 && datum.this.fertility>=7 && datum.this.fertility<=8.5 && datum.this.life_expect>=40 && datum.this.life_expect<=48"
        }
      ]
    },
    {
      "name": "outlier1980",
      "source": "interpolate",
      "transform": [
        { "type": "filter", "expr": "datum.isOutlier1980" },
        { "type": "collect", "sort": { "field": "this.fertility", "order": "descending" } },
        { "type": "window", "ops": [ "row_number" ], "as": [ "rn" ] },
        { "type": "filter", "expr": "datum.rn==1" }
      ]
    },
    {
      "name": "trackCountries",
      "on": [
        { "trigger": "active", "toggle": "{country: active.country}" }
      ]
    }
  ],
  "signals": [
    { "name": "minYear", "value": 1955 },
    { "name": "maxYear", "value": 2005 },
    { "name": "stepYear", "value": 5 },
    {
      "name": "active",
      "value": {},
      "on": [
        { "events": "@point:pointerdown, @point:touchstart", "update": "datum" },
        { "events": "window:pointerup, window:touchend", "update": "{}" }
      ]
    },
    { "name": "isActive", "update": "active.country" },
    {
      "name": "timeline",
