          "as": "label"
        },
        {
          "type": "formula",
          "expr": "datum['depth'] === 0 ? 0.12 : datum['depth'] === 1 ? 0.28 : 0.44",
          "as": "labelYFrac"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "color",
      "type": "ordinal",
      "domain": { "data": "tree", "field": "depth" },
      "range": { "scheme": "magma" }
    }
  ],
  "marks": [
    {
      "name": "background",
      "description": "An ivisible rect that covers the entire canvas and sits behind everything",
      "type": "rect",
      "encode": {
        "enter": {
          "x": { "signal": "-padding['left']" },
          "y": { "signal": "-padding['top']" },
          "width": { "signal": "width+padding['left']+padding['right']" },
          "height": { "signal": "height+padding['top']+padding['bottom']" },
          "fillOpacity": { "value": 0 }
        }
      }
    },
    {
      "name": "circles",
      "description": "the zoomable packed circles",
      "type": "symbol",
      "from": { "data": "tree" },
      "encode": {
        "enter": {
          "shape": { "value": "circle" },
          "fill": { "scale": "color", "field": "depth" },
          "cursor": { "value": "pointer" },
          "tooltip": { "field": "name" }
        },
        "update": {
          "x": {
            "signal": "lerp([root['x']+ (datum['x'] - focus0['x']) * focus0['k'], root['x'] + (datum['x'] - focus['x']) * k], tEase)"
          },
          "y": {
            "signal": "lerp([ root['y'] + (datum['y'] - focus0['y']) * focus0['k'],  root['y'] + (datum['y'] - focus['y']) * k], tEase)"
          },
          "size": {
            "signal": "pow(2*(datum['r'] * lerp([focus0['k'], k],tEase)),2)"
          },
          "fill": {
            "signal": "showDetails && focus['id'] === datum['id'] ? '#fff' : scale('color',datum['depth'])"
          },
          "zindex": {
            "signal": "!showDetails ? 1 : (focus['id'] === root['id'] && isValid(datum['parent'])) ? -99 : indexof(pluck(treeAncestors('tree', datum['id']), 'id'), focus['id']) > 0 ? -99 : 1"
          },
          "stroke": {
            "signal": "showDetails ? scale('color', datum['depth']) : luminance(scale('color', datum['depth'])) > 0.5 ?  'black' : 'white'"
          },
          "strokeWidth": {
            "signal": "focus['id'] === datum['id'] && showDetails ? 20 : 0.5"
          },
          "strokeOpacity": {
            "signal": "!showDetails ? 0.5 : focus['id'] === root['id'] ? min(tEase, 0.35) : min(tEaseDelayed, 0.35)"
          }
        },
        "hover": {
          "color": {
            "signal": "showDetails ? scale('color', datum['depth']) : luminance(scale('color', datum['depth'])) > 0.5 ?  'black' : 'white'"
          },
          "strokeWidth": { "value": 2 }
        }
      }
    },
    {
      "name": "depth_label_arrows",
      "description": "Arrows from explanatory labels to representative circles at each visible depth level.",
      "type": "path",
      "from": { "data": "label_targets" },
      "interactive": false,
      "encode": {
        "update": {
          "path": {
            "signal": "pathArrow({x: width*0.06, y: height*datum['labelYFrac']}, {x: lerp([root['x'] + (datum['x'] - focus0['x']) * focus0['k'], root['x'] + (datum['x'] - focus['x']) * k], tEase), y: lerp([root['y'] + (datum['y'] - focus0['y']) * focus0['k'], root['y'] + (datum['y'] - focus['y']) * k], tEase)}, 6, 10)"
          },
          "stroke": { "value": "#333" },
          "strokeWidth": { "value": 1.5 },
          "fill": { "value": "#333" },
          "opacity": { "signal": "showDetails ? 0 : (ceil(k) === 1 ? (isValid(t) ? tEaseDelayed : 1) : 0)" },
          "zindex": { "value": 50 }
        }
      }
    },
    {
      "name": "depth_labels",
      "description": "Text labels describing the hierarchy depth levels.",
      "type": "text",
      "from": { "data": "label_targets" },
      "interactive": false,
      "encode": {
        "enter": {
          "align": { "value": "left" },
          "baseline": { "value": "middle" },
          "fontSize": { "value": 12 },
          "fontWeight": { "value": "bold" }
        },
        "update": {
          "x": { "signal": "width*0.06" },
          "y": { "signal": "height*datum['labelYFrac']" },
          "text": { "signal": "datum['label']" },
          "fill": { "value": "#111" },
          "opacity": { "signal": "showDetails ? 0 : (ceil(k) === 1 ? (isValid(t) ? tEaseDelayed : 1) : 0)" },
          "zindex": { "value": 51 }
        }
      }
    },
    {
      "name": "details_title",
      "details": "the name of the node (appears on zoom)",
      "type": "text",
      "from": { "data": "details_data" },
      "interactive": false,
      "encode": {
        "enter": {
          "text": { "signal": "datum['name']" },
          "fill": { "scale": "color", "field": "depth" },
          "fontSize": { "signal": "0.055*width" },
          "align": { "value": "center" },
          "x": { "signal": "width/2" },
          "y": { "signal": "height/4" },
          "opacity": { "value": 0 }
        },
        "update": {
          "opacity": {
            "signal": "!showDetails ? 0 : focus['id'] === root['id'] ? tEase : tEaseDelayed"
          }
        }
      }
    },
    {
      "name": "details",
      "description": "additional information about the node (appears on zoom)",
      "type": "text",
      "from": { "data": "details_data" },
      "interactive": false,
      "encode": {
        "enter": {
          "text": { "signal": "datum['details']" },
          "fontSize": { "signal": "0.045*width" },
          "align": { "value": "center" },
          "x": { "signal": "width/2" },
          "y": { "signal": "height/3" },
          "fill": { "value": "gray" },
          "opacity": { "value": 0 }
        },
        "update": {
          "opacity": {
            "signal": "!showDetails ? 0 : focus['id'] === root['id'] ? tEase : tEaseDelayed"
          }
        }
      }
    },
    {
      "name": "helper_text",
      "interactive": false,
      "description": "interactivity instructions located at the bottom of left",
      "type": "text",
      "encode": {
        "enter": {
          "fontSize": { "value": 14 },
          "text": {
            "signal": "['interactivity instructions:', '• click on a node to zoom-in','• for nodes with children, shift + click to see details for that node', '• to slow down animations, ⌘ + click (Mac) / ⊞ + click (Windows)']"
          },
          "y": { "signal": "height+5" }
        },
        "update": {
          "opacity": {
            "signal": "ceil(k) === 1 ? isValid(t) ? tEaseDelayed : 1 : 0"
          }
        }
      }
    }
  ]
}
